import pytest

from versions.semver import is_valid_semver


@pytest.mark.parametrize('text', ['1.2.3', '0.0.0', '10.20.30', '1.0.0-alpha.1'])
def test_valid(text):
    assert is_valid_semver(text)


@pytest.mark.parametrize(
    'text', ['01.2.3', '1.02.3', '1.2', '1.2.3.4', 'v1.2.3', '', '1.2.3-']
)
def test_invalid(text):
    assert not is_valid_semver(text)
